window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-99"]=[{"id":"set2-oM2c9yhz","fingerprint":"156eb6a42989496b","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Care dintre următoarele afirmații subliniază corect necesitatea irigării endodontice, în completarea instrumentării mecanice?","options":[{"id":"A","text":"Irigarea endodontică este recomandată exclusiv la finalul tratamentului, după instrumentarea completă."},{"id":"B","text":"Zonele neinstrumentate, precum istmurile sau delta apicală, nu permit depozitarea microorganismelor."},{"id":"C","text":"Peste o treime din suprafața pereților sistemului endodontic nu este accesibilă instrumentării."},{"id":"D","text":"Detritusul dentinar (smear-layer) format în urma instrumentării este steril."},{"id":"E","text":"Instrumentarea reduce numărul microorganismelor într-o măsură suficientă pentru a asigura vindecarea."}],"correct":["C"],"pages":[144],"source":"set-2"},{"id":"set2-bJX4eB9b","fingerprint":"caf5c69392f76a92","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Ce consecințe pot avea zonele inaccesibile instrumentării, precum istmurile sau canalele laterale, dacă debridarea nu este completă?","options":[{"id":"A","text":"Se curăță eficient doar prin plasarea unui pansament temporar pe bază de hidroxid de calciu."},{"id":"B","text":"Favorizează vindecarea rapidă prin menținerea unui mediu umed în canalul radicular."},{"id":"C","text":"Permit o mai bună adaptare a materialelor de obturație de canal."},{"id":"D","text":"Depozitează resturi dentinare și microorganisme, putând duce la apariția leziunilor periapicale."},{"id":"E","text":"Sunt considerate zone sterile care nu necesită o atenție deosebită în timpul lavajului."}],"correct":["D"],"pages":[144],"source":"set-2"},{"id":"set2-2UgSMBjX","fingerprint":"f630bea658394fc2","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Referitor la proprietățile și utilizarea hipocloritului de sodiu în endodonție, care dintre următoarele afirmații sunt adevărate?","options":[{"id":"A","text":"Se utilizează în concentrație de 2,5 - 6% și devine iritant în concentrații de peste 6%."},{"id":"B","text":"Este soluția irigantă de elecție utilizată în lavajul sonic și ultrasonic."},{"id":"C","text":"Capacitatea sa de dizolvare tisulară crește odată cu scăderea temperaturii."},{"id":"D","text":"Acționează prin solubilizarea fracțiunii anorganice a detritusului dentinar."},{"id":"E","text":"Neutralizează lipopolizaharidele bacteriene."}],"correct":["A","B","E"],"pages":[144],"source":"set-2"},{"id":"set2-6-1U_cRx","fingerprint":"d5ef5a3808d7d2d3","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Ce efect are creșterea concentrației soluției de hipoclorit de sodiu în timpul irigării endodontice?","options":[{"id":"A","text":"Scade capacitatea de dizolvare a țesutului organic."},{"id":"B","text":"Crește efectul antibacterian, fără a modifica capacitatea de dizolvare a țesutului."},{"id":"C","text":"Nu are nicio influență asupra citotoxicității soluției."},{"id":"D","text":"Reduce efectul antibacterian, dar crește efectul de lubrifiere."},{"id":"E","text":"Crește capacitatea de dizolvare a țesutului și crește citotoxicitatea."}],"correct":["E"],"pages":[144],"source":"set-2"},{"id":"set2-PzVC2O0V","fingerprint":"2a8b8c2b58b444d3","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Care sunt aspectele corecte referitoare la secvențialitatea utilizării iriganților în tratamentul endodontic?","options":[{"id":"A","text":"Hipocloritul de sodiu se folosește exclusiv la final, după utilizarea chelatorilor."},{"id":"B","text":"Hipocloritul de sodiu se folosește în alternanță cu EDTA, având un efect complementar."},{"id":"C","text":"Hipocloritul de sodiu se utilizează în toate etapele instrumentării, urmat de chelatori (EDTA)."},{"id":"D","text":"Chelatorii precum EDTA sunt utilizați primii pentru a facilita penetrarea hipocloritului de sodiu."},{"id":"E","text":"Lavajul final este realizat exclusiv cu chelatori (EDTA) pentru a îndepărta smear-layer-ul."}],"correct":["B","C"],"pages":[144],"source":"set-2"},{"id":"set2-DQsL7-7D","fingerprint":"a1ce5d07655d6d7d","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Pe lângă concentrație, care dintre următorii factori sunt importanți pentru eficacitatea hipocloritului de sodiu ca irigant endodontic?","options":[{"id":"A","text":"Penetrabilitatea, care este dependentă de gradul de instrumentare."},{"id":"B","text":"Creșterea temperaturii, care influențează în mică măsură efectul antibacterian."},{"id":"C","text":"Alternanța exclusivă cu ser fiziologic pentru a reduce citotoxicitatea."},{"id":"D","text":"Culoarea soluției, care indică gradul de prospețime."},{"id":"E","text":"Volumul, timpul de expunere și reînnoirea soluției."}],"correct":["A","B","E"],"pages":[144],"source":"set-2"},{"id":"set2-NYQC-WO4","fingerprint":"f30bf4cffd2a57bb","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"În condițiile unei preparații adecvate a canalului radicular, care este distanța efectivă a acțiunii irigantului față de orificiul acului de irigare convențională?","options":[{"id":"A","text":"Depinde exclusiv de concentrația soluției"},{"id":"B","text":"1-2 mm"},{"id":"C","text":"4-5 mm"},{"id":"D","text":"2-3 mm"},{"id":"E","text":"Pe întreaga lungime de lucru"}],"correct":["B"],"pages":[145],"source":"set-2"},{"id":"set2-VT9Er5hw","fingerprint":"3eadd2d17b441a09","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Care dintre următoarele reprezintă dezavantaje ale utilizării hipocloritului de sodiu ca soluție de irigare endodontică?","options":[{"id":"A","text":"Îndepărtarea incompletă a biofilmului."},{"id":"B","text":"Miros și gust neplăcut."},{"id":"C","text":"Efect citotoxic în caz de extrudare periapicală."},{"id":"D","text":"Acțiune de lubrifiere insuficientă."},{"id":"E","text":"Nu îndepărtează detritusurile."}],"correct":["A","B","C","E"],"pages":[145],"source":"set-2"},{"id":"set2-_LX-9LTu","fingerprint":"eb79925e797335f9","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Referitor la acțiunea antibacteriană a hipocloritului de sodiu, care afirmație este corectă?","options":[{"id":"A","text":"Este eficientă doar împotriva bacteriilor gram-pozitive."},{"id":"B","text":"Este potențată de prezența resturilor de țesut pulpar în canalul radicular."},{"id":"C","text":"S-a demonstrat a fi eficientă împotriva Enterococcus Faecalis."},{"id":"D","text":"Acționează asupra unui număr mare de specii microbiene, inclusiv fungi și virusuri."},{"id":"E","text":"Se datorează ionilor de sodiu din soluție."}],"correct":["D"],"pages":[145],"source":"set-2"},{"id":"set2-kmHuYGhI","fingerprint":"7008a9f9ff1549ce","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"În timpul irigării unui canal radicular, un pacient acuză brusc o durere puternică, cu senzație de arsură, urmată de tumefierea rapidă a zonei și apariția unei echimoze. Care este conduita imediată corectă?","options":[{"id":"A","text":"Obturarea de urgență a canalului radicular pentru a sigila apexul."},{"id":"B","text":"Aplicarea unei comprese calde pe zona afectată pentru a favoriza vasodilatația."},{"id":"C","text":"Prescrierea imediată de antibiotice, fără alte măsuri locale."},{"id":"D","text":"Oprirea irigării, aspirarea soluției din canal și aplicarea unei comprese reci."},{"id":"E","text":"Continuarea irigării cu o soluție de concentrație mai mică."}],"correct":["D"],"pages":[145],"source":"set-2"},{"id":"set2-bYGXFODZ","fingerprint":"52ae0123ee9c11b0","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Care dintre următoarele măsuri contribuie la prevenirea accidentelor legate de utilizarea hipocloritului de sodiu?","options":[{"id":"A","text":"Fixarea acului la pereții laterali ai canalului pentru a asigura o irigare țintită."},{"id":"B","text":"Prepararea unui canal cu formă conică."},{"id":"C","text":"Utilizarea unui ac de irigare care ajunge exact pe lungimea de lucru."},{"id":"D","text":"Injectarea lentă a soluției, cu presiune mică."},{"id":"E","text":"Asigurarea posibilității de refluare a soluției de irigare."}],"correct":["B","D","E"],"pages":[145],"source":"set-2"},{"id":"set2-JqvAPfRi","fingerprint":"f76976b4d4cd6e2f","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Ce metode pot fi utilizate pentru a potența acțiunea hipocloritului de sodiu la concentrații mai mici?","options":[{"id":"A","text":"Utilizarea alternativă cu agenți chelatori."},{"id":"B","text":"Creșterea timpului de contact, fără reînnoirea soluției."},{"id":"C","text":"Agitarea mecanică, sonică sau ultrasonică."},{"id":"D","text":"Creșterea tensiunii superficiale a soluției."},{"id":"E","text":"Răcirea soluției sub temperatura camerei."}],"correct":["A","C"],"pages":[145],"source":"set-2"},{"id":"set2-psEaNzWp","fingerprint":"c02b132c08d3522e","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Care este un efect negativ potențial al utilizării unei concentrații ridicate de hipoclorit de sodiu asupra structurii dentare?","options":[{"id":"A","text":"Creșterea elasticității și rezistenței dentinei."},{"id":"B","text":"Vulnerabilizarea structurii dentinare."},{"id":"C","text":"Reducerea efectului de lubrifiere a instrumentelor."},{"id":"D","text":"Remineralizarea canaliculelor dentinare."},{"id":"E","text":"Scăderea citotoxicității periapicale."}],"correct":["B"],"pages":[145],"source":"set-2"},{"id":"set2-hFs70ToE","fingerprint":"1db1686d132a7c71","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Care este efectul încălzirii soluției de hipoclorit de sodiu asupra eficacității sale?","options":[{"id":"A","text":"Crește acțiunea germicidă împotriva Enterococcus Faecalis."},{"id":"B","text":"Mărește semnificativ eficacitatea de solvent și efectul antibacterian."},{"id":"C","text":"Scade stabilitatea soluției, făcând-o ineficientă la 37°C."},{"id":"D","text":"Reduce citotoxicitatea soluției în cazul extruziei periapicale."},{"id":"E","text":"Nu îi mărește semnificativ eficacitatea, deoarece clorul activ este disipat mai rapid."}],"correct":["E"],"pages":[145],"source":"set-2"},{"id":"set2-bAnUH-6L","fingerprint":"ed8d7ef9d6e6021c","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Care sunt afirmațiile corecte cu privire la utilizarea soluției de hipoclorit de sodiu încălzită în tratamentul endodontic?","options":[{"id":"A","text":"La temperatura de 37⁰ C, soluția încălzită rămâne stabilă timp de 60 de minute."},{"id":"B","text":"Clorul activ este disipat mai lent la temperaturi ridicate, crescând efectul antibacterian."},{"id":"C","text":"Încălzirea soluției se poate realiza exclusiv în recipiente speciale, înainte de a fi aspirată în seringă."},{"id":"D","text":"Creșterea temperaturii mărește semnificativ eficacitatea sa de solvent tisular."},{"id":"E","text":"La temperatura de 45⁰ C, soluția își menține stabilitatea timp de o oră."}],"correct":["A","E"],"pages":[146],"source":"set-2"},{"id":"set2-n8gXXXc8","fingerprint":"80cf8f823af5e625","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Ce acțiune specifică au agenții chelatori, precum EDTA și acidul citric, la nivelul canalului radicular?","options":[{"id":"A","text":"Au un efect antibacterian primar prin afectarea citoplasmei celulelor bacteriene."},{"id":"B","text":"Induc formarea unui strat protector de smear layer pe pereții canalului."},{"id":"C","text":"Acționează asupra fracțiunii organice, dizolvând resturile de țesut pulpar."},{"id":"D","text":"Se leagă de ionii de Ca²⁺ din hidroxiapatita dentinară."},{"id":"E","text":"Sunt utilizați în concentrație de 10% pentru EDTA și 15%-17% pentru acidul citric."}],"correct":["D"],"pages":[146],"source":"set-2"},{"id":"set2-b4lwTIx8","fingerprint":"70388adb5f0eecfb","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Referitor la modalitățile de utilizare a agenților chelatori, care dintre următoarele afirmații sunt corecte?","options":[{"id":"A","text":"Acțiunea lor lubrifiantă este caracteristică formei de soluție, nu celei de gel."},{"id":"B","text":"Sub formă de gel, sunt utilizați pentru irigarea finală, după terminarea instrumentării."},{"id":"C","text":"Utilizarea soluției de agent chelator poate fi urmată de o irigare finală cu hipoclorit de sodiu."},{"id":"D","text":"Sub formă de soluție, se utilizează pentru un timp de contact de 1-3 minute pentru a îndepărta detritusurile."},{"id":"E","text":"Induc o mai bună adaptare a materialului de obturație la pereții laterali ai canalului radicular."}],"correct":["C","D","E"],"pages":[146],"source":"set-2"},{"id":"set2-Xu4AXgC1","fingerprint":"8721d375b898d37d","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Care sunt proprietățile și limitele gluconatului de clorhexidină în irigarea canalului radicular?","options":[{"id":"A","text":"Contactul cu hipocloritul de sodiu duce la formarea unui precipitat carcinogenetic numit paracloranilină."},{"id":"B","text":"Are o acțiune eficientă asupra biofilmului bacterian."},{"id":"C","text":"Poate înlocui hipocloritul de sodiu datorită efectului său de dizolvare a substratului organic."},{"id":"D","text":"Mecanismul său antimicrobian se bazează pe afectarea citoplasmei celulelor bacteriene planctonice."},{"id":"E","text":"Studiile recente au demonstrat o acțiune antibacteriană foarte puternică."}],"correct":["A","D"],"pages":[146],"source":"set-2"},{"id":"set2-3AzFkvMg","fingerprint":"5d748cc732be3753","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Ce caracteristici definitorii are soluția de irigare MTAD (Biopure)?","options":[{"id":"A","text":"Este utilizată pentru irigarea inițială a canalului, înainte de instrumentare."},{"id":"B","text":"Are în componență un antibiotic (Doxiciclina), acid citric și un detergent."},{"id":"C","text":"Principalul său scop este dizolvarea țesutului necrotic din sistemul endodontic."},{"id":"D","text":"Rolul său este îndepărtarea smear layer-ului la finalul tratamentului."},{"id":"E","text":"Se folosește în conjuncție cu hipocloritul de sodiu."}],"correct":["B","D","E"],"pages":[146],"source":"set-2"},{"id":"set2-YVTAblsn","fingerprint":"b686ace414c424d2","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Care sunt aspectele importante legate de tehnica de irigare a canalului radicular și limitările acesteia?","options":[{"id":"A","text":"Tehnica de irigare convențională permite dirijarea eficientă a soluției în zone neinstrumentabile precum istmurile."},{"id":"B","text":"Blocarea acului în canal previne extruzia soluției de irigare dincolo de foramenul apical."},{"id":"C","text":"Zonele neinstrumentabile pot conține bacterii, resturi de țesut necrotic și de dentină."},{"id":"D","text":"Activarea soluției irigante este necesară pentru a deplasa soluția în zonele greu accesibile."},{"id":"E","text":"Acele de irigare trebuie să prezinte orificii sau fante laterale pentru a preveni accidentele."}],"correct":["C","D","E"],"pages":[146],"source":"set-2"},{"id":"set2-ukyH6QMX","fingerprint":"61d257874bede9e9","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Care dintre următoarele metode sunt considerate sisteme speciale pentru activarea soluției irigante în canalul radicular?","options":[{"id":"A","text":"Sisteme bazate pe agenți chelatori în formă de gel."},{"id":"B","text":"Sisteme ultrasonice."},{"id":"C","text":"Sisteme sonice."},{"id":"D","text":"Sisteme de activare prin radiații laser."},{"id":"E","text":"Sisteme de irigare manuală cu presiune pozitivă."}],"correct":["B","C","D"],"pages":[146],"source":"set-2"},{"id":"set2-r5Xoj9gi","fingerprint":"3b2dfdaa68b1528b","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Care sunt caracteristicile sistemului de irigare sonică EndoActivator?","options":[{"id":"A","text":"Utilizează un ac din titan cu suprafața netedă pentru a evita instrumentarea pereților."},{"id":"B","text":"Acele utilizate sunt din material plastic pentru a se conforma traiectoriei canalare."},{"id":"C","text":"Oscilația sonică poate duce la fatigabilitatea biofilmului."},{"id":"D","text":"Produce fenomene de cavitație și turbulență acustică în lichidul de irigație."},{"id":"E","text":"Oscilează cu o frecvență cuprinsă între 2000 și 10000 de cicli pe minut."}],"correct":["B","C","E"],"pages":[147],"source":"set-2"},{"id":"set2-PAPsa2KE","fingerprint":"1d4912b7dc1abd7e","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Ce fenomene și efecte sunt asociate cu irigarea ultrasonică în endodonție?","options":[{"id":"A","text":"Creșterea temperaturii hipocloritului de sodiu."},{"id":"B","text":"Fragmentarea și împrăștierea debriurilor în soluția de irigație."},{"id":"C","text":"Cavitația, care determină forțe de forfecare ce favorizează desprinderea debriurilor."},{"id":"D","text":"Utilizarea unei microcanule care aspiră soluția irigantă sub presiune negativă."},{"id":"E","text":"Oscilarea unui ac din material plastic pentru a produce fatigabilitatea biofilmului."}],"correct":["A","B","C"],"pages":[147],"source":"set-2"},{"id":"set2-OmzIaptJ","fingerprint":"d40d00fb9d6dbea3","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Care este protocolul operator corect pentru utilizarea sistemului de irigație ultrasonic Endo-Ultra?","options":[{"id":"A","text":"Se repetă cicluri de activare și aspirare a soluției timp de 1-3 minute, menținând contactul cu pereții laterali."},{"id":"B","text":"Se utilizează la începutul tratamentului, în timpul sondării canalului, împreună cu gel de EDTA."},{"id":"C","text":"Acul cu conicitate de 2% trebuie să instrumenteze activ pereții dentinari pentru o curățare eficientă."},{"id":"D","text":"Se utilizează o piesă de mână cu cablu care emite oscilații sonice cu frecvență de până la 10000 cicli/min."},{"id":"E","text":"Se introduce acul în canalul plin cu hipoclorit până la 1 mm de lungimea de lucru și se activează timp de 30 - 60 de secunde."}],"correct":["E"],"pages":[147],"source":"set-2"},{"id":"set2-k3eCOtxd","fingerprint":"ddfed0e561e49ec0","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Ce afirmații sunt corecte în legătură cu activarea soluției de irigare prin radiații laser?","options":[{"id":"A","text":"Se aplică pe parcursul tratamentului mecano-chimic, după fiecare instrument."},{"id":"B","text":"Mecanismul său principal de acțiune este generarea de forțe de forfecare prin cavitație."},{"id":"C","text":"Fibra laser poate fi staționară sau deplasată în sens corono-apical în canalul radicular."},{"id":"D","text":"Are capacitatea de a elimina complet biofilmul bacterian de pe pereții canalului radicular."},{"id":"E","text":"Favorizează pătrunderea irigantului în tubulii dentinari la o profunzime similară cu cea a distribuției microorganismelor."}],"correct":["C","E"],"pages":[147],"source":"set-2"},{"id":"set2-SvDJnwMC","fingerprint":"78d8ffe6d94a630e","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Care este principalul avantaj al sistemelor cu presiune negativă, precum EndoVac?","options":[{"id":"A","text":"Utilizarea unui ac de plastic care oscilează pentru a se conforma traiectoriei canalare."},{"id":"B","text":"Creșterea temperaturii soluției de hipoclorit pentru o acțiune mai eficientă."},{"id":"C","text":"Reducerea biofilmului bacterian prin emiterea de impulsuri de radiație."},{"id":"D","text":"Obținerea unui control mai bun în regiunea ultimilor milimetri apicali prin aspirarea soluției."},{"id":"E","text":"Generarea de turbulență acustică pentru fragmentarea debriurilor tisulare."}],"correct":["D"],"pages":[147],"source":"set-2"},{"id":"set2-gHqGyUGe","fingerprint":"6eb512a74176cf33","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Ce metode sunt descrise pentru realizarea agitării mecanice în cadrul irigației convenționale?","options":[{"id":"A","text":"Utilizarea unui aparat piezo-electric care produce vibrații de înaltă frecvență."},{"id":"B","text":"Mișcarea acului de irigare în direcție apico-coronară în timpul instrumentării."},{"id":"C","text":"Introducerea unei fibre laser staționare în camera pulpară."},{"id":"D","text":"Deplasarea unui con de gutapercă cu o amplitudine de 2 mm în canalul umplut cu hipoclorit."},{"id":"E","text":"Aplicarea acestor mișcări în irigația convențională cu volum mare de irigant."}],"correct":["B","D","E"],"pages":[147],"source":"set-2"},{"id":"set2-VaXJj5KN","fingerprint":"23ab191c58799522","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Conform secvenței unui tratament endodontic, când și cum se realizează irigarea canalului radicular?","options":[{"id":"A","text":"Hipocloritul de sodiu în concentrație de 2,5%-6% poate fi utilizat în alternanță cu soluția de EDTA."},{"id":"B","text":"Doar la finalul tratamentului mecano-chimic, pentru a activa soluția de irigare."},{"id":"C","text":"Pe tot parcursul tratamentului, utilizând hipoclorit de sodiu după fiecare instrument."},{"id":"D","text":"La începutul tratamentului, în timpul sondării canalului."},{"id":"E","text":"Exclusiv cu gel de EDTA, aplicat o singură dată la începutul tratamentului."}],"correct":["A","C","D"],"pages":[147],"source":"set-2"},{"id":"set2-DvQ7wtz5","fingerprint":"ec10eaf7f9721a82","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Care dintre următoarele afirmații descriu corect etapele irigării canalului radicular în timpul tratamentului endodontic?","options":[{"id":"A","text":"Pe parcursul tratamentului mecanico-antiseptic, se utilizează hipoclorit de sodiu în concentrație de 2,5%-6% după fiecare instrument."},{"id":"B","text":"La finalul tratamentului, se poate utiliza EDTA sau acid citric, aplicat timp de 1 minut per canal."},{"id":"C","text":"Hipocloritul de sodiu este utilizat exclusiv la finalul tratamentului pentru a îndepărta smear-layer-ul."},{"id":"D","text":"Utilizarea succesivă a hipocloritului de sodiu și a EDTA la finalul tratamentului este o procedură fără riscuri pentru pereții dentinari."},{"id":"E","text":"La începutul tratamentului, în faza de sondare a canalului, se utilizează gel de EDTA."}],"correct":["A","B","E"],"pages":[148],"source":"set-2"},{"id":"set2-ipYyzTTD","fingerprint":"9ab27f86591d39a0","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Ce rol specific îndeplinește EDTA în cadrul protocolului de irigare a canalului radicular?","options":[{"id":"A","text":"Generează o turbulență foto-acustică indusă de fotoni pentru o curățare superioară."},{"id":"B","text":"Are un efect antibacterian moderat, inferior hipocloritului de sodiu."},{"id":"C","text":"Reprezintă mediul standard de irigație utilizat pe tot parcursul preparației canalului."},{"id":"D","text":"Contribuie la vindecarea leziunilor periapicale prin inducerea formării de țesut calcificat."},{"id":"E","text":"Îndepărtează detritusul dentinar, cunoscut sub denumirea de smear-layer."}],"correct":["E"],"pages":[148],"source":"set-2"},{"id":"set2-b8ff7eHT","fingerprint":"dcfcb69a726b8e52","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Prin ce se diferențiază activarea sonică de cea ultrasonică a soluțiilor de lavaj endodontic?","options":[{"id":"A","text":"Prin eficiență, doar activarea ultrasonică reușind să distribuie soluția în anatomia complexă a sistemului endodontic."},{"id":"B","text":"Prin amplitudinea oscilațiilor, care la dispozitivele sonice este mai mare (în jur de 20000 Hz)."},{"id":"C","text":"Prin modul de inserție în canal, pila ultrasonică aplicându-se doar la nivelul cavității de acces."},{"id":"D","text":"Prin amplitudinea oscilațiilor, care este mai mică la dispozitivele sonice (1500-6000Hz) comparativ cu cele ultrasonice."},{"id":"E","text":"Prin tipul de irigant utilizat, activarea sonică fiind compatibilă doar cu clorhexidina."}],"correct":["D"],"pages":[148],"source":"set-2"},{"id":"set2-JPBq2svx","fingerprint":"9fe1ace73c9c3722","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Care sunt scopurile utilizării pansamentului medicamentos cu hidroxid de calciu în tratamentul endodontic?","options":[{"id":"A","text":"Neutralizarea endotoxinelor prezente în dentină."},{"id":"B","text":"Asigurarea unei dezinfecții complete, eliminând întregul spectru bacterian din canalul radicular."},{"id":"C","text":"Îndepărtarea eficientă a detritusului dentinar (smear-layer) de pe pereții canalului."},{"id":"D","text":"Inducerea mineralizării (apexogeneza, apexificare) la dinții imaturi, infectați, cu apex deschis."},{"id":"E","text":"Combaterea resorbției radiculare post-traumatice."}],"correct":["A","D","E"],"pages":[148],"source":"set-2"},{"id":"set2-s6CkKYLC","fingerprint":"087e3e3497ca9f67","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Care afirmații referitoare la timpul de acțiune și efectele pansamentului cu hidroxid de calciu sunt corecte?","options":[{"id":"A","text":"Efectul antibacterian crește continuu pe măsură ce pansamentul este menținut mai mult de 14 zile."},{"id":"B","text":"O singură aplicare, pentru un interval de 1-2 săptămâni, este considerată suficientă pentru a obține o încărcătură microbiană redusă."},{"id":"C","text":"Prelungirea duratei pansamentului duce la un efect de vulnerabilizare a dentinei."},{"id":"D","text":"Efectul dezinfectant optim se obține în decurs de 7 zile, perioadă în care pH-ul atinge valoarea de 12,5."},{"id":"E","text":"Menținerea pe termen lung a pansamentului îmbunătățește calitatea restaurării temporare."}],"correct":["B","C","D"],"pages":[148],"source":"set-2"},{"id":"set2-OVqDs671","fingerprint":"87dc70873ea85c28","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Ce particularitate prezintă tehnica ERBIUM laser, bazată pe PIPS (turbulență foto-acustică indusă de fotoni)?","options":[{"id":"A","text":"Implică aplicarea instrumentarului specific la nivelul cavității de acces, nu în interiorul canalului radicular."},{"id":"B","text":"Este o tehnică de irigație pasivă, fără agitare a soluției de lavaj."},{"id":"C","text":"Utilizează o pilă endosonică ce se introduce până în treimea apicală a canalului."},{"id":"D","text":"Se bazează pe o frecvență de oscilație în jur de 20000 Hz."},{"id":"E","text":"Funcționează pe principiul presiunii negative pentru a curăța sistemul endodontic."}],"correct":["A"],"pages":[148],"source":"set-2"},{"id":"set2-69oDwz7O","fingerprint":"06d3336a60027505","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Care sunt indicațiile pentru utilizarea pe termen lung a pansamentului medicamentos cu hidroxid de calciu?","options":[{"id":"A","text":"Rădăcini incomplet formate."},{"id":"B","text":"Replantare după avulsie traumatică."},{"id":"C","text":"Apexificare."},{"id":"D","text":"Exudat sever periapical."},{"id":"E","text":"Resorbție externă inflamatorie progresivă."}],"correct":["A","D","E"],"pages":[149],"source":"set-2"},{"id":"set2-ke_6Bp03","fingerprint":"84ae2883b7172775","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Ce proprietăți caracterizează hidroxidul de calciu în contextul tratamentului endodontic?","options":[{"id":"A","text":"Combate exudatul prin eliberarea ionului hidroxil și prin proprietățile sale antibacteriene."},{"id":"B","text":"Hidrolizează fracțiunea lipidică a lipopolizaharidelor bacteriene."},{"id":"C","text":"Exercită un efect antimicrobian eficient asupra tuturor germenilor din sistemul endodontic."},{"id":"D","text":"Are un efect antibacterian datorită pH-ului său acid."},{"id":"E","text":"Acțiunea sa antimicrobiană este extinsă, nefiind limitată de distanța față de locul aplicării."}],"correct":["A","B"],"pages":[149],"source":"set-2"},{"id":"set2-E76IRa8u","fingerprint":"aa5668ac8d8a6275","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"În cazul utilizării hidroxidului de calciu pentru apexificare, care este protocolul recomandat și rezultatul urmărit?","options":[{"id":"A","text":"Schimbarea pastei la 3 luni pentru a constitui la nivelul foramenului apical o barieră de osteodentină."},{"id":"B","text":"Menținerea pastei timp de 6 luni pentru a induce formarea de țesut de granulație."},{"id":"C","text":"Schimbarea pastei la 1-2 săptămâni pentru a forma o barieră de cement."},{"id":"D","text":"Schimbarea pastei lunar pentru a continua formarea rădăcinii cu țesut osos."},{"id":"E","text":"Aplicare unică pentru a permite formarea unei bariere de dentină secundară."}],"correct":["A"],"pages":[149],"source":"set-2"},{"id":"set2--x63SRPu","fingerprint":"3567103324dd5288","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Care este efectul hidroxidului de calciu rezidual asupra sigilanților pe bază de eugenat de zinc și ce se recomandă pentru îndepărtarea sa?","options":[{"id":"A","text":"Compromite adeziunea și accelerează priza; se recomandă utilizarea EDTA și lărgirea canalului cu un instrument adițional."},{"id":"B","text":"Îmbunătățește adeziunea sigilantului și se recomandă irigarea cu hipoclorit de sodiu."},{"id":"C","text":"Nu are niciun efect asupra sigilantului, dar se recomandă lărgirea preventivă a canalului."},{"id":"D","text":"Încetinește priza sigilantului și nu necesită măsuri speciale de îndepărtare."},{"id":"E","text":"Accelerează priza fără a afecta adeziunea; se recomandă simpla irigare cu ser fiziologic."}],"correct":["A"],"pages":[149],"source":"set-2"},{"id":"set2-Y94UckGe","fingerprint":"8445fbce82899c2d","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Ce limitări prezintă hidroxidul de calciu în ceea ce privește acțiunea sa antimicrobiană în sistemul endodontic?","options":[{"id":"A","text":"Determină liza completă a tuturor componentelor lipopolizaharidelor bacteriene."},{"id":"B","text":"E. faecalis poate forma un biofilm chiar și după aplicarea de hidroxid de calciu."},{"id":"C","text":"Biofilmul endodontic rămâne intact chiar și în urma tratamentului."},{"id":"D","text":"Este ineficient împotriva enterococilor și actinomicetelor."},{"id":"E","text":"Acțiunea sa antimicrobiană este limitată la distanță de locul aplicării."}],"correct":["B","C","D","E"],"pages":[149],"source":"set-2"},{"id":"set2-OLqU9lTz","fingerprint":"b2f1da958c36fc00","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Care este intervalul de timp recomandat pentru o singură aplicare de hidroxid de calciu în prima ședință de tratament endodontic pentru a reduce încărcătura microbiană?","options":[{"id":"A","text":"3-5 zile"},{"id":"B","text":"1-2 săptămâni"},{"id":"C","text":"24 de ore"},{"id":"D","text":"3 luni"},{"id":"E","text":"3-4 săptămâni"}],"correct":["B"],"pages":[149],"source":"set-2"},{"id":"set2-lcgm-E-k","fingerprint":"3c1f2c3bd74024c8","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Care sunt consecințele și limitările instrumentării mecanice a sistemului endodontic?","options":[{"id":"A","text":"Instrumentarea asigură accesul în toate detaliile anatomice ale sistemului endodontic, inclusiv în delta apicală și istmusuri."},{"id":"B","text":"În urma instrumentării se formează detritus dentinar (smear-layer), care este colonizat de microorganisme."},{"id":"C","text":"Instrumentarea mecanică elimină în totalitate microorganismele, fiind suficientă pentru prevenirea parodontitei apicale."},{"id":"D","text":"Zonele neinstrumentate pot reține microorganisme și produșii lor de metabolism, împiedicând adaptarea materialelor de obturație de canal."},{"id":"E","text":"Mai mult de o treime din suprafața pereților sistemului endodontic nu este accesibilă instrumentării."}],"correct":["B","D","E"],"pages":[144],"source":"set-2"},{"id":"set2-rMGdG9u9","fingerprint":"5e3e84c66682ca51","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Care sunt obiectivele și metodele prin care se realizează dezinfecția canalelor radiculare?","options":[{"id":"A","text":"Principalul scop al preparației canalului radicular este eliminarea florei microbiene, a țesutului necrotic, infectat și a țesutului pulpar vital."},{"id":"B","text":"Dezinfecția corectă previne apariția leziunilor periapicale favorizate de prezența zonelor neinstrumentate."},{"id":"C","text":"Irigarea endodontică se realizează exclusiv la finalul tratamentului mecanic, fiind contraindicată pe parcursul instrumentării."},{"id":"D","text":"Dezinfecția chimică se bazează exclusiv pe aplicarea pansamentelor temporare, irigarea fiind o procedură facultativă."},{"id":"E","text":"Pansamentul temporar pe bază de hidroxid de calciu poate fi utilizat între ședințe pentru a completa dezinfecția chimică."}],"correct":["A","B","E"],"pages":[144],"source":"set-2"},{"id":"set2-ua9woguX","fingerprint":"bbbbab8a489ba170","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Care este motivul principal pentru care instrumentarea exclusiv mecanică a canalului radicular conduce la apariția leziunilor periapicale și împiedică o bună adaptare a materialelor de obturație?","options":[{"id":"A","text":"Absența completă a detritusului dentinar (smear-layer) în urma unei preparații mecanice standard."},{"id":"B","text":"Îndepărtarea excesivă a țesutului pulpar vital, care lasă canalele laterale expuse mediului extern."},{"id":"C","text":"Efectul irigării endodontice desfășurate pe tot parcursul tratamentului, care antrenează flora microbiană în țesuturile periapicale."},{"id":"D","text":"Utilizarea pansamentelor temporare pe bază de hidroxid de calciu modifică structural pereții dentinari."},{"id":"E","text":"Prezența zonelor neinstrumentate care depozitează resturi dentinare, microorganisme și produșii lor de metabolism."}],"correct":["E"],"pages":[144],"source":"set-2"},{"id":"set2-mz1hbsAT","fingerprint":"3a0f529adbb70175","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Care sunt factorii care impun utilizarea irigării endodontice (dezinfecția chimică) ca etapă indispensabilă a tratamentului?","options":[{"id":"A","text":"Faptul că instrumentarea mecanică nu reușește să elimine deloc microorganismele din canalul principal."},{"id":"B","text":"Imposibilitatea accesării a mai mult de o treime din suprafața pereților sistemului endodontic doar prin instrumentare mecanică."},{"id":"C","text":"Prezența unor detalii anatomice complexe precum delta apicală și istmusurile, unde instrumentarul nu poate pătrunde."},{"id":"D","text":"Formarea detritusului dentinar (smear-layer) colonizat bacterian în urma instrumentării mecanice."},{"id":"E","text":"Necesitatea dizolvării complete a materialelor de obturație provizorie pe bază de hidroxid de calciu înainte de obturația de canal."}],"correct":["B","C","D"],"pages":[144],"source":"set-2"},{"id":"set2-4GEo5QiS","fingerprint":"9dea24f4a1ae1264","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Care dintre următoarele aspecte caracterizează acțiunea antibacteriană și de dizolvare a hipocloritului de sodiu în irigarea endodontică?","options":[{"id":"A","text":"Creșterea temperaturii soluției mărește semnificativ efectul său antibacterian și de solvent tisular."},{"id":"B","text":"Acțiunea sa germicidă acoperă în mod eficient tulpini de Enterococcus faecalis."},{"id":"C","text":"Acțiunea antibacteriană se realizează în principal prin dizolvarea fracțiunii anorganice a sistemului endodontic."},{"id":"D","text":"Prezența resturilor de țesut pulpar și a exudatului periapical afectează eficiența sa germicidă."},{"id":"E","text":"Neutralizarea lipopolizaharidelor bacteriene are loc pe fondul reducerii toxicității irigantului la concentrații de peste 6%."}],"correct":["D"],"pages":[145],"source":"set-2"},{"id":"set2-Fqr_IElT","fingerprint":"3c4f52990928d56c","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Care sunt măsurile procedurale și anatomice necesare pentru ca soluția de hipoclorit de sodiu să asigure o acțiune dezinfectantă eficientă?","options":[{"id":"A","text":"Menținerea acului exact pe toată lungimea de lucru pe parcursul irigării convenționale."},{"id":"B","text":"Reînnoirea frecventă a soluției de irigare în interiorul sistemului canalar."},{"id":"C","text":"Realizarea contactului soluției cu toată suprafața canalului, în mod particular în regiunea apicală."},{"id":"D","text":"Fixarea acului la nivelul pereților laterali ai canalului radicular pentru a asigura livrarea soluției sub presiune ridicată."},{"id":"E","text":"Prepararea canalului într-o formă conică, permițând amplasarea acului la o distanță de 2-3 mm față de lungimea de lucru."}],"correct":["B","C","E"],"pages":[145],"source":"set-2"},{"id":"set2-O_kTVHdA","fingerprint":"bad5b48f1060a7b1","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Ce efecte și dezavantaje sunt asociate utilizării hipocloritului de sodiu în tratamentul endodontic?","options":[{"id":"A","text":"Acțiunea sa antimicrobiană este însoțită de îndepărtarea completă a biofilmului și a detritusurilor din canalele radiculare."},{"id":"B","text":"Efectul irigant este resimțit pe o distanță limitată la 1-2 mm de orificiul acului de irigare."},{"id":"C","text":"Extruzia dincolo de foramenul apical poate determina tumefiere, echimoze, hematoame și parestezii."},{"id":"D","text":"Utilizarea unor concentrații ridicate crește elasticitatea și rezistența structurală a dentinei radiculare."},{"id":"E","text":"Creșterea concentrației soluției mărește capacitatea de dizolvare tisulară concomitent cu creșterea citotoxicității."}],"correct":["B","C","E"],"pages":[145],"source":"set-2"},{"id":"set2-9vEh1-RU","fingerprint":"ab8cdb21d5251d2f","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Care este atitudinea terapeutică indicată în situația în care pacientul acuză durere puternică și senzație de arsură ca urmare a extruziei hipocloritului de sodiu în periapex?","options":[{"id":"A","text":"Oprirea irigării, aspirarea soluției din canalul radicular și aplicarea unei comprese reci pe zona afectată."},{"id":"B","text":"Activarea sonică a soluției de irigare pentru neutralizarea imediată a toxicității tisulare periapicale."},{"id":"C","text":"Continuarea irigării exclusiv cu ser fiziologic și aplicarea unei comprese calde pe zona tumefiată."},{"id":"D","text":"Fixarea acului la nivelul pereților laterali ai canalului și aspirarea sub presiune ridicată a exudatului periapical."},{"id":"E","text":"Injectarea rapidă a unei soluții de EDTA pentru chelarea ionilor de hipoclorit din spațiul periapical."}],"correct":["A"],"pages":[145],"source":"set-2"},{"id":"set2-g_0QRTdE","fingerprint":"13f558d595bf41c2","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Ce rol și caracteristici prezintă soluția MTAD utilizată în irigarea sistemului endodontic?","options":[{"id":"A","text":"Compoziția sa include un antibiotic, acid citric și un agent detergent."},{"id":"B","text":"Efectul său principal constă în lubrifierea canalelor radiculare pentru a preveni fractura instrumentarului rotativ."},{"id":"C","text":"Este destinată utilizării în etapele inițiale ale instrumentării pentru debridarea primară a canalului radicular."},{"id":"D","text":"Se folosește împreună cu hipocloritul de sodiu deoarece nu posedă un efect propriu de dizolvare tisulară."},{"id":"E","text":"Se utilizează la finalul tratamentului mecano-chimic având ca scop îndepărtarea smear layer-ului."}],"correct":["A","D","E"],"pages":[146],"source":"set-2"},{"id":"set2-L4pceM16","fingerprint":"bb1e0787cb389815","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la agenții chelatori utilizați în tratamentul endodontic?","options":[{"id":"A","text":"Acidul citric este utilizat uzual ca agent chelator în concentrație de 15% - 17%."},{"id":"B","text":"Acționează asupra fracțiunii anorganice din canalul radicular prin legarea de ionii de Ca²⁺ din hidroxiapatita dentinei radiculare."},{"id":"C","text":"Soluția de acid etilendiaminotetraacetic este utilizată cel mai frecvent în concentrații cuprinse între 15% și 17%."},{"id":"D","text":"Îndepărtarea stratului de smear layer facilitează pătrunderea agenților antibacterieni în zonele profunde ale dentinei."},{"id":"E","text":"Sub formă de gel, se utilizează pentru irigarea canalului timp de 1-3 minute după terminarea instrumentării."}],"correct":["B","C","D"],"pages":[146],"source":"set-2"},{"id":"set2-lHMaovXo","fingerprint":"af0adaf1cac088aa","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Din ce motiv gluconatul de clorhexidină nu poate înlocui hipocloritul de sodiu în timpul tratamentului mecanic al canalului radicular?","options":[{"id":"A","text":"Formează un precipitat brun-portocaliu la contactul cu detritusurile dentinare."},{"id":"B","text":"Nu posedă capacitatea de a dizolva substratul organic."},{"id":"C","text":"Acționează exclusiv asupra biofilmului bacterian, fără a disocia."},{"id":"D","text":"Nu acționează asupra celulelor bacteriene planctonice."},{"id":"E","text":"Acțiunea sa antibacteriană este extrem de puternică și deteriorează structura peretelui dentinar."}],"correct":["B"],"pages":[146],"source":"set-2"},{"id":"set2-JaWw0wkU","fingerprint":"6a16a2cb3ec7daf7","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Ce consecință are contactul direct dintre clorhexidină și hipocloritul de sodiu în interiorul canalului radicular?","options":[{"id":"A","text":"Evaporarea rapidă a clorhexidinei cu eliberare masivă de compuși gazoși."},{"id":"B","text":"Inactivarea reciprocă și formarea unui strat dens de smear layer organic."},{"id":"C","text":"Apariția paracloranilinei, un precipitat brun-portocaliu cu potențial carcinogenetic."},{"id":"D","text":"Potențarea efectului de dizolvare a fracțiunii anorganice a dentinei."},{"id":"E","text":"Formarea unui precipitat de culoare alb-gălbuie care neutralizează capacitatea de adeziune a sigilanților."}],"correct":["C"],"pages":[146],"source":"set-2"},{"id":"set2-Ub3waEkQ","fingerprint":"8fd3ac2009243552","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Care sunt particularitățile utilizării agenților chelatori sub formă de soluție sau gel în endodonție?","options":[{"id":"A","text":"Agenții chelatori scad capacitatea de adeziune a sigilanților la dentină prin saturarea canaliculelor dentinare."},{"id":"B","text":"Soluțiile de chelatori dizolvă atât substratul organic, cât și pe cel anorganic, putând înlocui complet hipocloritul de sodiu."},{"id":"C","text":"Irigarea cu soluție de agent chelator poate fi urmată de o irigare finală cu hipoclorit de sodiu."},{"id":"D","text":"Utilizarea agenților chelatori sub formă de soluție se realizează timp de 1-3 minute, după terminarea instrumentării."},{"id":"E","text":"Agenții sub formă de gel sunt utilizați frecvent în timpul negocierii canalului radicular datorită acțiunii lubrifiante."}],"correct":["C","D","E"],"pages":[146],"source":"set-2"},{"id":"set2-neopXXIa","fingerprint":"621f5154acb79b49","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Care dintre următoarele afirmații descriu corect acțiunile soluțiilor de irigare în endodonție?","options":[{"id":"A","text":"Clorhexidina disociază la nivelul canalului radicular, acționând puternic asupra biofilmului bacterian aderent."},{"id":"B","text":"Clorhexidina prezintă o acțiune antibacteriană foarte puternică, care se menține stabilă în prezența biofilmului."},{"id":"C","text":"Clorhexidina își bazează proprietățile antimicrobiene pe afectarea citoplasmei celulelor bacteriene planctonice."},{"id":"D","text":"Acidul citric acționează asupra fracțiunii anorganice prin legarea de ionii de Ca²⁺ din hidroxiapatita dentinei radiculare."},{"id":"E","text":"Chelatorii induc o adaptare superioară a materialului de obturație la nivelul pereților laterali ai canalului radicular."}],"correct":["C","D","E"],"pages":[146],"source":"set-2"},{"id":"set2-k2y17m9T","fingerprint":"44422bd993084d92","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Care dintre următoarele caracteristici sunt specifice irigației ultrasonice a canalelor radiculare?","options":[{"id":"A","text":"Acele ultrasonice necesită o introducere activă, în contact strâns cu pereții laterali ai canalului."},{"id":"B","text":"Sistemul Endo-Ultra este prevăzut cu ace confecționate din titan, cu o conicitate de 4%."},{"id":"C","text":"Protocolul operator pentru sistemul Endo-Ultra indică activarea acului timp de 30-60 secunde."},{"id":"D","text":"Fenomenul de cavitație indus determină apariția unor forțe de forfecare."},{"id":"E","text":"Este produsă de aparate piezo-electrice care emit vibrații cu o frecvență ridicată."}],"correct":["C","D","E"],"pages":[147],"source":"set-2"},{"id":"set2-su4Twz4l","fingerprint":"d396951e71f8bb7b","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Care este particularitatea tehnică esențială a sistemului PIPS (turbulență foto-acustică indusă de fotoni) cu laser ERBIUM?","options":[{"id":"A","text":"Utilizează ace din material plastic pentru a asigura flexibilitatea și a preveni fracturarea în treimea apicală."},{"id":"B","text":"Se bazează pe oscilarea unui ac flexibil cu o frecvență cuprinsă între 2000 și 10000 cicli/minut."},{"id":"C","text":"Necesită introducerea fibrei laser până la 1 mm de lungimea de lucru și activarea timp de 1-3 minute."},{"id":"D","text":"Implică aplicarea pilei endosonice la nivelul cavității de acces, fără a fi introdusă în canalul radicular."},{"id":"E","text":"Determina o eliminare completă a biofilmului bacterian din anatomia complexă a sistemului endodontic."}],"correct":["D"],"pages":[148],"source":"set-2"},{"id":"set2-plFYKz5i","fingerprint":"25b4bc372b142310","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Ce substanțe și protocoale sunt recomandate pe parcursul etapelor de irigare a canalului radicular?","options":[{"id":"A","text":"Clorhexidina înlocuiește hipocloritul de sodiu în etapele intermediare datorită efectului său antibacterian superior și dizolvării tisulare."},{"id":"B","text":"Hipocloritul de sodiu reprezintă mediul standard de irigație, utilizat în concentrație de 2,5%-6% pe parcursul tratamentului mecanico-antiseptic."},{"id":"C","text":"Succesiunea soluțiilor la finalul preparării consolidează structura dentinară, prevenind orice risc de eroziune a pereților canalului."},{"id":"D","text":"La începutul tratamentului endodontic, pentru sondarea canalului, se utilizează gel de EDTA."},{"id":"E","text":"La finalul tratamentului endodontic, se recomandă utilizarea de EDTA sau acid citric, în cantitate de 1 ml/canal, timp de 1 minut."}],"correct":["B","D","E"],"pages":[147],"source":"set-2"},{"id":"set2-bBHJzJxk","fingerprint":"019d766394a2090e","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Care dintre următoarele mecanisme sunt implicate în agitarea mecanică și irigarea cu presiune negativă?","options":[{"id":"A","text":"Irigația cu presiune negativă limitează penetrarea soluției de lavaj la nivelul istmusurilor inter-canalare și al canalelor curbe."},{"id":"B","text":"Mișcarea acului de irigare în direcție apico-coronară în timpul instrumentării constituie o metodă de agitare mecanică."},{"id":"C","text":"Mișcările cu amplitudine redusă ale conului de gutapercă previn complet deplasarea soluției spre pereții laterali ai canalului."},{"id":"D","text":"Dispozitivul EndoVac aspiră soluția irigantă prin intermediul unei microcanule, asigurând un control în ultimii milimetri apicali."},{"id":"E","text":"Agitarea mecanică poate fi realizată la finalul preparării prin deplasarea unui con de gutapercă cu o amplitudine de 2 mm."}],"correct":["B","D","E"],"pages":[147],"source":"set-2"},{"id":"set2-NvVeGKRh","fingerprint":"60358318d9ac01fa","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Care este diferența tehnică fundamentală între activarea sonică și cea ultrasonică a soluțiilor de irigare?","options":[{"id":"A","text":"Oscilațiile dispozitivelor sonice variază între 1500 și 6000 Hz, în timp ce dispozitivele ultrasonice prezintă oscilații de aproximativ 20000 Hz."},{"id":"B","text":"Activarea sonică induce fenomene intense de cavitație, în timp ce irigarea ultrasonică acționează strict prin forțe de forfecare pasive."},{"id":"C","text":"Activarea ultrasonică folosește în mod exclusiv ace din material plastic pentru a se conforma curburilor severe."},{"id":"D","text":"Irigarea ultrasonică determină scăderea temperaturii hipocloritului de sodiu, efect neregăsit la irigarea sonică."},{"id":"E","text":"Dispozitivele sonice funcționează la o frecvență de aproximativ 20000 Hz, iar cele ultrasonice au variații între 1500 și 6000 Hz."}],"correct":["A"],"pages":[148],"source":"set-2"},{"id":"set2-ae1V7yWb","fingerprint":"1d586a51f6314597","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Care dintre următoarele situații clinice reprezintă indicații de elecție pentru aplicarea tratamentului cu hidroxid de calciu pe perioade lungi de timp?","options":[{"id":"A","text":"Exudatul sever periapical."},{"id":"B","text":"Rădăcinile incomplet formate."},{"id":"C","text":"Resorbția externă inflamatorie progresivă."},{"id":"D","text":"Infecțiile radiculare dominate exclusiv de enterococi și actinomicete."},{"id":"E","text":"Timpul insuficient pentru finalizarea tratamentului endodontic într-o singură ședință."}],"correct":["A","B","C"],"pages":[149],"source":"set-2"},{"id":"set2-BsdTfZVN","fingerprint":"5f1ed21f81490b12","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Prin ce mecanisme și caracteristici se definește acțiunea hidroxidului de calciu utilizat ca pansament medicamentos în sistemul endodontic?","options":[{"id":"A","text":"Atinge un efect optim dezinfectant în decurs de 7 zile, în paralel cu o creștere a pH-ului până la valoarea de 12,5."},{"id":"B","text":"Hidrolizează fracțiunea lipidică a lipopolizaharidelor bacteriene."},{"id":"C","text":"Efectul antimicrobian se propagă fără limitări la distanță de locul aplicării, conferind rezultate in vivo complet predictibile."},{"id":"D","text":"Rolul de combatere a exudatului radicular este condiționat exclusiv de constituirea barierei de osteodentină."},{"id":"E","text":"Acționează eficient asupra întregului spectru bacterian, asigurând o eradicare microbiană completă după 14 zile."}],"correct":["A","B"],"pages":[148],"source":"set-2"},{"id":"set2-xf79jPOB","fingerprint":"aea1b47eacf40fcd","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Care este protocolul recomandat pentru gestionarea hidroxidului de calciu rezidual înainte de obturarea de canal, luând în considerare interacțiunea acestuia cu sigilantul pe bază de eugenat de zinc?","options":[{"id":"A","text":"Se introduce clorhexidină pentru precipitarea hidroxidului de calciu sub forma unui complex anorganic inert."},{"id":"B","text":"Se utilizează soluție EDTA pentru neutralizarea reziduurilor și se lărgește canalul cu un instrument având un număr adițional față de cel utilizat la lungimea de lucru."},{"id":"C","text":"Se instrumentează canalul exclusiv cu același instrument master, sub irigare abundentă cu ser fiziologic."},{"id":"D","text":"Se aplică o soluție intens acidă cu scopul de a scădea pH-ul sub 7 și a întârzia priza sigilantului pe bază de eugenat de zinc."},{"id":"E","text":"Se utilizează hipoclorit de sodiu în concentrație ridicată exclusiv pentru dizolvarea chimică a hidroxidului de calciu din treimea apicală."}],"correct":["B"],"pages":[149],"source":"set-2"},{"id":"set2-TwS6Xnpq","fingerprint":"d1219c7672435919","chapterId":"set-2","subchapterId":"set2-2.04","type":"CM","text":"Din ce motive se recomandă evitarea menținerii prelungite a pansamentului medicamentos cu hidroxid de calciu în tratamentul endodontic standard?","options":[{"id":"A","text":"Calitatea restaurării coronare temporare suferă o diminuare într-un interval scurt de timp."},{"id":"B","text":"Inițiază rapid și ireversibil fenomenele de resorbție radiculară apicală externă."},{"id":"C","text":"Efectul antibacterian se plafonează și nu înregistrează o creștere direct proporțională cu timpul."},{"id":"D","text":"Generează un efect de vulnerabilizare a țesutului dentinar."},{"id":"E","text":"Determină o scădere bruscă a pH-ului canalicular la valori acide, ceea ce favorizează multiplicarea germenilor patogeni."}],"correct":["A","C","D"],"pages":[148],"source":"set-2"},{"id":"set2-fFK7ut9X","fingerprint":"ceb7362994cc28d5","chapterId":"set-2","subchapterId":"set2-2.04","type":"CS","text":"Care afirmație descrie corect interacțiunea dintre hidroxidul de calciu și biofilmul format de Enterococcus faecalis în sistemul endodontic?","options":[{"id":"A","text":"Efectul intens alcalin dezintegrează complet matricea extracelulară a oricărui biofilm microbian în decurs de cel mult 14 zile."},{"id":"B","text":"Enterococcus faecalis deține un potențial nativ de a forma și susține un biofilm inclusiv în urma aplicării hidroxidului de calciu."},{"id":"C","text":"Hidroxidul de calciu joacă un rol determinant și semnificativ în profilaxia infecțiilor post-tratament declanșate de enterococi."},{"id":"D","text":"Hidroxidul de calciu previne formarea biofilmului de Enterococcus faecalis exclusiv prin eliberarea ionilor de sodiu la nivel periapical."},{"id":"E","text":"Eradicarea speciei Enterococcus faecalis se obține exclusiv prin reînnoirea pastei de hidroxid de calciu la intervale de 3 luni."}],"correct":["B"],"pages":[149],"source":"set-2"}];
